const STORAGE_KEY="bucho-today-records-v1",BASE_KEY="bucho-today-base-v1",PATCH_KEY="bucho-today-task-patches-v1",DEVICE_KEY="bucho-today-device-v1",LOGIN_KEY="bucho-today-login-v1",SETTINGS_KEY="bucho-today-settings-v1";
const SYSTEM_PREFIX="ZZZ-TC-",DEPENDENCY_PREFIX=`${SYSTEM_PREFIX}DEPENDENCY-`,CALENDAR_PREFIX=`${SYSTEM_PREFIX}CALENDAR-`;
const DEFAULT_SETTINGS={owner:"福本",dayStart:"08:00",dayEnd:"20:00",lunchStart:"12:00",lunchEnd:"13:00",buffer:30};
const SECTIONS=["守る","進める","育てる"],TEMPS=["🔥HOT","🟠WARM","🧊COLD"],STATUSES=["未着手","進行中","確認待ち","保留","完了"];
