function configReady(){return CONFIG.CLIENT_ID&&!CONFIG.CLIENT_ID.includes("YOUR_")&&CONFIG.REDIRECT_URI&&!CONFIG.REDIRECT_URI.includes("YOUR-");}
async function initializeAuth(){if(!configReady()){setSync("warn","Microsoft設定待ち");return;}state.msal=new PublicClientApplication({auth:{clientId:CONFIG.CLIENT_ID,authority:CONFIG.AUTHORITY,redirectUri:CONFIG.REDIRECT_URI,navigateToLoginRequestUrl:false},cache:{cacheLocation:"localStorage",storeAuthStateInCookie:true}});await state.msal.initialize();const response=await state.msal.handleRedirectPromise();state.account=response?.account||state.msal.getAllAccounts()[0]||null;if(state.account){state.msal.setActiveAccount(state.account);localStorage.setItem(LOGIN_KEY,state.account.username||"");await sync({automatic:true});}updateAccount();}
async function login(){if(!state.msal)return alert("先にapp-config.jsへClient IDと公開URLを設定してください。");await state.msal.loginRedirect({scopes:CONFIG.GRAPH_SCOPES,prompt:"select_account",redirectUri:CONFIG.REDIRECT_URI});}
async function token(){if(!state.account)throw new Error("Microsoftログインが必要です");try{return(await state.msal.acquireTokenSilent({scopes:CONFIG.GRAPH_SCOPES,account:state.account})).accessToken;}catch(e){if(e instanceof InteractionRequiredAuthError||/interaction_required|consent_required|login_required/i.test(e.errorCode||"")){await state.msal.acquireTokenRedirect({scopes:CONFIG.GRAPH_SCOPES,account:state.account,redirectUri:CONFIG.REDIRECT_URI,loginHint:state.account.username||localStorage.getItem(LOGIN_KEY)||undefined});return null;}throw e;}}
function graphError(response,payload={}){const e=new Error(payload?.error?.message||`HTTP ${response.status}`);e.errorCode=`GRAPH_${response.status}_${payload?.error?.code||"HTTP"}`;e.httpStatus=response.status;return e;}
const fileMetaUrl=name=>`https://graph.microsoft.com/v1.0/me/drive/special/approot:/${encodeURIComponent(name)}?$select=id,name,eTag,lastModifiedDateTime,webUrl,size`;
async function fetchFile(tok,name,parser){await fetch("https://graph.microsoft.com/v1.0/me/drive/special/approot?$select=id",{headers:{Authorization:`Bearer ${tok}`}});const mr=await fetch(fileMetaUrl(name),{headers:{Authorization:`Bearer ${tok}`}});if(mr.status===404)return{exists:false,records:{},bytes:null,id:"",eTag:"",webUrl:""};if(!mr.ok){let p={};try{p=await mr.json();}catch{}throw graphError(mr,p);}const meta=await mr.json(),cr=await fetch(`https://graph.microsoft.com/v1.0/me/drive/items/${encodeURIComponent(meta.id)}/content`,{headers:{Authorization:`Bearer ${tok}`}});if(!cr.ok)throw graphError(cr);const bytes=await cr.arrayBuffer(),list=await parser(bytes),records={};list.forEach(r=>records[r.id]=r);return{exists:true,records,bytes,id:meta.id,eTag:meta.eTag,webUrl:meta.webUrl||""};}
async function uploadFile(tok,name,bytes,remote,mime){const headers={Authorization:`Bearer ${tok}`,"Content-Type":mime,Accept:"application/json"};if(remote?.eTag)headers["If-Match"]=remote.eTag;const url=remote?.id?`https://graph.microsoft.com/v1.0/me/drive/items/${encodeURIComponent(remote.id)}/content`:`https://graph.microsoft.com/v1.0/me/drive/special/approot:/${encodeURIComponent(name)}:/content`,response=await fetch(url,{method:"PUT",headers,body:bytes});if(!response.ok){let p={};try{p=await response.json();}catch{}throw graphError(response,p);}return response.json();}
function recordSignature(r){return JSON.stringify([r.id,r.date,r.kind,r.sourceId,r.title,r.subtitle,r.start,r.end,r.plannedHours,r.section,r.todayDone,r.focusRank,r.sortOrder,r.notes,r.value,r.updatedAt,r.updatedBy,r.revision,r.deleted]);}
function mergeToday(remote,manual){const merged={},conflicts=[],ids=new Set([...Object.keys(state.records),...Object.keys(remote)]);for(const id of ids){const l=state.records[id],r=remote[id],b=state.base[id];if(!l){merged[id]=r;continue;}if(!r){merged[id]=l;continue;}if(recordSignature(l)===recordSignature(r)){merged[id]=Date.parse(l.updatedAt)>=Date.parse(r.updatedAt)?l:r;continue;}const lc=!b||recordSignature(l)!==recordSignature(b),rc=!b||recordSignature(r)!==recordSignature(b);if(lc&&rc){conflicts.push(id);merged[id]=manual&&confirm(`TODAYの「${l.title||r.title}」が別端末でも変更されています。\n\nOK：この端末を優先\nキャンセル：OneDriveを優先`)?l:r;}else merged[id]=lc?l:rc?r:Date.parse(l.updatedAt)>=Date.parse(r.updatedAt)?l:r;}return{merged,conflicts};}
async function applyTaskPatches(tok,remote,automatic){const patches=Object.entries(state.taskPatches);if(!patches.length)return remote;const records={...remote.records};for(const [taskId,patch] of patches){const task=records[taskId];if(!task)continue;const conflict=Object.keys(patch.changes).some(key=>String(task[key]??"")!==String(patch.baseValues[key]??""));if(conflict&&automatic)throw Object.assign(new Error(`TASK CONTROLとの同期競合：${patch.title}`),{errorCode:"TASK_CONFLICT"});if(conflict&&!confirm(`「${patch.title}」はTASK CONTROL側でも変更されています。\n\nOK：TODAYの変更を優先\nキャンセル：TASK CONTROLを優先`))continue;Object.assign(task,patch.changes,{updatedAt:nowIso(),updatedBy:deviceId(),revision:(Number(task.revision)||0)+1});}
  const bytes=await buildTaskWorkbook(Object.values(records),remote.bytes),uploaded=await uploadFile(tok,CONFIG.TASK_FILE_NAME,bytes,remote,TASK_MIME);state.taskPatches={};return{...remote,records,bytes,id:uploaded.id||remote.id,eTag:uploaded.eTag||remote.eTag,webUrl:uploaded.webUrl||remote.webUrl};}
async function fetchEvents(tok){const start=`${state.date}T00:00:00+09:00`,end=`${addDays(state.date,1)}T00:00:00+09:00`,url=`https://graph.microsoft.com/v1.0/me/calendarView?startDateTime=${encodeURIComponent(start)}&endDateTime=${encodeURIComponent(end)}&$select=id,subject,start,end,location,isAllDay,isCancelled,webLink&$orderby=start/dateTime`;
  const response=await fetch(url,{headers:{Authorization:`Bearer ${tok}`,Accept:"application/json",Prefer:'outlook.timezone="Tokyo Standard Time"'}});if(!response.ok){let p={};try{p=await response.json();}catch{}throw graphError(response,p);}state.events=(await response.json()).value?.filter(e=>!e.isCancelled)||[];}
async function sync({automatic=false}={}){if(!state.account||state.busy)return false;clearTimeout(state.syncTimer);state.busy=true;$("syncBtn").disabled=true;setSync("working","同期中…");try{await ensureJsZip();const tok=await token();if(!tok)return false;let taskRemote=await fetchFile(tok,CONFIG.TASK_FILE_NAME,parseTaskWorkbook);if(!taskRemote.exists)throw new Error("TASK_CONTROL_Master.xlsxが見つかりません。同じClient IDとOneDrive AppFolderを使用してください。");taskRemote=await applyTaskPatches(tok,taskRemote,automatic);state.taskRemote=taskRemote;state.tasks=taskRemote.records;
    const todayRemote=await fetchFile(tok,CONFIG.TODAY_FILE_NAME,parseTodayWorkbook),result=mergeToday(todayRemote.records,!automatic);if(result.conflicts.length&&automatic)throw Object.assign(new Error(`TODAY同期競合 ${result.conflicts.length}件`),{errorCode:"TODAY_CONFLICT"});const template=todayRemote.bytes||await(await fetch(new URL("./BUCHO_TODAY_Master.xlsx",document.baseURI))).arrayBuffer(),bytes=await buildTodayWorkbook(Object.values(result.merged),template),uploaded=await uploadFile(tok,CONFIG.TODAY_FILE_NAME,bytes,todayRemote,TODAY_MIME);state.records=result.merged;state.base=structuredClone(result.merged);state.todayRemote={...todayRemote,id:uploaded.id||todayRemote.id,eTag:uploaded.eTag||todayRemote.eTag,webUrl:uploaded.webUrl||todayRemote.webUrl};await fetchEvents(tok);store();setSync("synced",`同期成功｜${tokyoTime()}`);state.lastError=null;render();return true;
  }catch(e){state.lastError={code:e.errorCode||e.name,message:String(e.message||e)};setSync("error",`同期失敗｜${state.lastError.code}`);if(!automatic)alert(`${state.lastError.message}\n\nExcel Masterを閉じ、同じMicrosoftアカウントで再度お試しください。`);return false;}finally{state.busy=false;$("syncBtn").disabled=false;}}
function scheduleSync(delay=CONFIG.AUTO_SYNC_DELAY_MS||6000,message=""){clearTimeout(state.syncTimer);setSync("local",state.account?`${message||"変更を端末内保存"}｜自動同期待ち`:message||"端末内保存");if(state.account)state.syncTimer=setTimeout(()=>sync({automatic:true}),delay);}
function setSync(cls,text){const indicator=$("syncState"),button=$("syncBtn");if(indicator){indicator.className=`sync-indicator ${cls}`;indicator.textContent=text;}if(button){button.textContent=cls==="working"?"↻ 同期中…":"↻ 同期";button.setAttribute("aria-busy",String(cls==="working"));}}
function updateAccount(){$("loginBtn").textContent=state.account?"アカウント切替":"Microsoftログイン";$("accountInfo").textContent=state.account?(state.account.username||state.account.name||"Microsoft接続済"):"Microsoft未接続";$("taskExcelBtn").disabled=!state.taskRemote?.id;$("todayExcelBtn").disabled=!state.todayRemote?.id;}
async function openExcel(which){const remote=which==="task"?state.taskRemote:state.todayRemote;if(!remote?.id)return;const popup=window.open("about:blank","_blank");try{const tok=await token(),response=await fetch(`https://graph.microsoft.com/v1.0/me/drive/items/${encodeURIComponent(remote.id)}/preview`,{method:"POST",headers:{Authorization:`Bearer ${tok}`,"Content-Type":"application/json"},body:"{}"}),payload=await response.json();if(!response.ok)throw graphError(response,payload);popup.location.replace(payload.getUrl);}catch(e){popup?.close();alert(e.message);}}

function changeDate(delta){state.date=addDays(state.date,delta);state.events=[];render();if(state.account)token().then(t=>t&&fetchEvents(t).then(render)).catch(()=>{});}
function openCandidates(){$("candidateList").innerHTML=candidateRows(carryTasks(),true);$("candidateDialog").showModal();}
function saveSettings(event){event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries());state.settings={owner:String(data.owner||"福本").trim(),buffer:Math.max(0,Math.min(70,Number(data.buffer)||0)),dayStart:data.dayStart,dayEnd:data.dayEnd,lunchStart:data.lunchStart,lunchEnd:data.lunchEnd};if(timeToMin(state.settings.dayEnd)<=timeToMin(state.settings.dayStart)){alert("表示終了は表示開始より後にしてください。");return;}store();$("settingsDialog").close();render();}
function openSettings(){const f=$("settingsForm");Object.entries(state.settings).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v;});$("settingsDialog").showModal();}
function diagnostics(){return JSON.stringify({appVersion:CONFIG.APP_VERSION,checkedAtTokyo:new Intl.DateTimeFormat("ja-JP",{timeZone:"Asia/Tokyo",dateStyle:"medium",timeStyle:"medium"}).format(new Date()),date:state.date,configuredRedirectUri:CONFIG.REDIRECT_URI,clientId:CONFIG.CLIENT_ID,signedIn:Boolean(state.account),account:state.account?.username||null,taskCount:activeTasks().length,todayPlanCount:plans().length,eventCount:state.events.length,pendingTaskPatchCount:Object.keys(state.taskPatches).length,todayRecordCount:Object.keys(state.records).length,settings:state.settings,lastError:state.lastError},null,2);}

$("prevDay").onclick=()=>changeDate(-1);$("nextDay").onclick=()=>changeDate(1);$("calendarBtn").onclick=()=>{state.date=tokyoDate();changeDate(0);};$("rebuildBtn").onclick=buildAutomaticPlan;$("confirmBtn").onclick=()=>{saveDayState({confirmed:!dayState().confirmed});render();};$("syncBtn").onclick=()=>state.account?sync():login();$("loginBtn").onclick=login;$("settingsBtn").onclick=openSettings;$("allTasksBtn").onclick=openCandidates;$("carryBtn").onclick=()=>$("carryDialog").showModal();$("planForm").onsubmit=savePlan;$("removePlanBtn").onclick=removePlan;$("settingsForm").onsubmit=saveSettings;
$("closeDayBtn").onclick=()=>{const current=dayState().closed;if(!current){const reflection=prompt("今日の振り返りを一言で残しますか？",dayState().reflection||"");if(reflection===null)return;saveDayState({closed:true,confirmed:true,reflection,closedAt:nowIso()});}else if(confirm("今日を再び開きますか？"))saveDayState({closed:false});render();};
$("interruptMemo").onchange=e=>saveMemo(e.target.value);$("promptGrid").onchange=e=>{if(e.target.dataset.prompt)savePrompt(e.target.dataset.prompt,e.target.value);};
$("timeline").onclick=e=>{if(Date.now()<state.justDraggedUntil)return;const task=e.target.closest("[data-task]"),event=e.target.closest("[data-event]");if(task)openPlan(task.dataset.task);else if(event){const item=state.events.find(x=>x.id===event.dataset.event);if(item?.webLink)window.open(item.webLink,"_blank","noopener");}};
$("timeline").addEventListener("dragstart",event=>{const bar=event.target.closest(".gantt-bar.task-bar.draggable");if(!bar)return;state.draggingPlan=bar.dataset.task;const plan=state.records[state.draggingPlan],rect=bar.getBoundingClientRect(),grabRatio=Math.max(0,Math.min(1,(event.clientX-rect.left)/Math.max(1,rect.width)));state.dragOffsetMinutes=grabRatio*duration(plan.start,plan.end);state.dragPreviewTime=timeToMin(plan.start);bar.classList.add("dragging");document.querySelector(".timeline-panel")?.classList.add("drag-active");event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",state.draggingPlan);showDragPreview(state.dragPreviewTime);});
$("timeline").addEventListener("dragover",event=>{if(!state.draggingPlan||!event.target.closest(".gantt-track,.gantt-time-header"))return;event.preventDefault();event.dataTransfer.dropEffect="move";showDragPreview(dragMinute(event));});
$("timeline").addEventListener("drop",event=>{if(!state.draggingPlan)return;event.preventDefault();const planId=state.draggingPlan,minute=dragMinute(event);state.justDraggedUntil=Date.now()+500;clearDragPreview();if(minute!==null)movePlanAndRebuild(planId,minute);});
$("timeline").addEventListener("dragend",()=>{state.justDraggedUntil=Date.now()+500;clearDragPreview();});
$("sectionCards").onclick=e=>{const target=e.target.closest("[data-plan]");if(target)openPlan(target.dataset.plan);};$("focusList").onclick=e=>{const target=e.target.closest("[data-plan]");if(target)openPlan(target.dataset.plan);};$("candidateList").onclick=e=>{const target=e.target.closest("[data-add-task]");if(target)addTaskToToday(target.dataset.addTask);};
$("todayExcelBtn").onclick=()=>openExcel("today");$("taskExcelBtn").onclick=()=>openExcel("task");$("diagnosticBtn").onclick=()=>{$("diagnosticText").textContent=diagnostics();$("diagnosticDialog").showModal();};document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>b.closest("dialog").close());
window.addEventListener("online",()=>state.account&&sync({automatic:true}));window.addEventListener("resize",()=>{updateNowLine();updateGanttVisibleCount();},{passive:true});document.addEventListener("visibilitychange",()=>document.visibilityState==="visible"&&state.account&&sync({automatic:true}));setInterval(()=>state.account&&sync({automatic:true}),Math.max(1,CONFIG.AUTO_PULL_MINUTES||3)*60000);setInterval(updateNowLine,30000);
render();initializeAuth().catch(e=>{state.lastError={code:e.errorCode||e.name,message:String(e.message||e)};setSync("error",`認証初期化失敗｜${state.lastError.code}`);});
